package com.example.editor.integration.compiler;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Test;
import com.example.editor.integration.InjectionFileOwnership;
import com.example.editor.integration.IntegrationArtifactKind;
import com.example.editor.integration.IntegrationDiagnostic;
import com.example.editor.integration.IntegrationDiagnosticSeverity;
import com.example.editor.integration.IntegrationTechnology;

class TechnologyCompilerServiceTests {
    @Test void registersAndResolvesAdapters(){var adapter=adapter(IntegrationTechnology.EMF,validResult(IntegrationTechnology.EMF));var registry=new TechnologyAdapterRegistry(List.of(adapter));assertThat(registry.require(IntegrationTechnology.EMF)).isSameAs(adapter);}
    @Test void rejectsDuplicateAdapters(){assertThatThrownBy(()->new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,validResult(IntegrationTechnology.EMF)),adapter(IntegrationTechnology.EMF,validResult(IntegrationTechnology.EMF))))).isInstanceOf(IllegalStateException.class);}
    @Test void rejectsMissingAdapter(){var registry=new TechnologyAdapterRegistry(List.of());assertThatThrownBy(()->registry.require(IntegrationTechnology.EMF)).isInstanceOf(TechnologyCompilationException.class);}
    @Test void requiresCanonicalSemanticRoot(){var request=TechnologyAdapterTestFixtures.emfRequest();var without=new TechnologyCompilationRequest(request.profile(),List.of(),"test",Map.of());var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,validResult(IntegrationTechnology.EMF)))));assertThatThrownBy(()->service.compile(without)).hasMessageContaining("semantic root");}
    @Test void acceptsGrammarRootWhenAdapterDeclaresGrammarAsRoot(){var request=TechnologyAdapterTestFixtures.langiumGrammarFirstRequest();var result=validResult(IntegrationTechnology.LANGIUM);var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(grammarRootAdapter(IntegrationTechnology.LANGIUM,result))));assertThat(service.compile(request)).isSameAs(result);}
    @Test void rejectsGrammarRootWhenArtifactIsSupportedButNotAutonomous(){var request=TechnologyAdapterTestFixtures.langiumGrammarFirstRequest();var result=validResult(IntegrationTechnology.LANGIUM);var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.LANGIUM,result))));assertThatThrownBy(()->service.compile(request)).hasMessageContaining("adapter accepts").hasMessageContaining("METAMODEL");}
    @Test void rejectsMismatchedAdapterResult(){var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,validResult(IntegrationTechnology.SIRIUS_DESKTOP)))));assertThatThrownBy(()->service.compile(TechnologyAdapterTestFixtures.emfRequest())).hasMessageContaining("mismatched");}
    @Test void rejectsDuplicatePaths(){var file=file("same.txt");var result=new TechnologyCompilationResult(IntegrationTechnology.EMF,List.of(file,file),List.of(),List.of(),List.of("rollback"),List.of(),List.of(),Map.of());var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,result))));assertThatThrownBy(()->service.compile(TechnologyAdapterTestFixtures.emfRequest())).hasMessageContaining("duplicate");}
    @Test void rejectsValidEmptyOutput(){var result=new TechnologyCompilationResult(IntegrationTechnology.EMF,List.of(),List.of(),List.of(),List.of("rollback"),List.of(),List.of(),Map.of());var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,result))));assertThatThrownBy(()->service.compile(TechnologyAdapterTestFixtures.emfRequest())).hasMessageContaining("at least one");}
    @Test void acceptsAValidCompilation(){var result=validResult(IntegrationTechnology.EMF);var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter(IntegrationTechnology.EMF,result))));assertThat(service.compile(TechnologyAdapterTestFixtures.emfRequest())).isSameAs(result);}
    @Test void requiresUnsupportedArtifactsToBeReported(){var request=TechnologyAdapterTestFixtures.siriusRequest();var adapter=new TechnologyAdapter(){public IntegrationTechnology technology(){return IntegrationTechnology.SIRIUS_DESKTOP;}public Set<IntegrationArtifactKind> supportedArtifactKinds(){return Set.of(IntegrationArtifactKind.METAMODEL);}public TechnologyCompilationResult compile(TechnologyCompilationRequest ignored){return validResult(IntegrationTechnology.SIRIUS_DESKTOP);}};var service=new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter)));assertThatThrownBy(()->service.compile(request)).hasMessageContaining("unsupported artifact");}
    @Test void acceptsExplicitUnsupportedWarning(){var request=TechnologyAdapterTestFixtures.siriusRequest();var warning=new IntegrationDiagnostic(IntegrationDiagnosticSeverity.WARNING,"UNSUPPORTED_ARTIFACT","people-editor","editor","partial");var result=new TechnologyCompilationResult(IntegrationTechnology.SIRIUS_DESKTOP,List.of(file("one.txt")),List.of(),List.of(),List.of("rollback"),List.of(),List.of(warning),Map.of());var adapter=new TechnologyAdapter(){public IntegrationTechnology technology(){return IntegrationTechnology.SIRIUS_DESKTOP;}public Set<IntegrationArtifactKind> supportedArtifactKinds(){return Set.of(IntegrationArtifactKind.METAMODEL);}public TechnologyCompilationResult compile(TechnologyCompilationRequest ignored){return result;}};assertThat(new TechnologyCompilerService(new TechnologyAdapterRegistry(List.of(adapter))).compile(request).valid()).isTrue();}

    private TechnologyAdapter adapter(IntegrationTechnology technology,TechnologyCompilationResult result){return new TechnologyAdapter(){public IntegrationTechnology technology(){return technology;}public Set<IntegrationArtifactKind> supportedArtifactKinds(){return java.util.EnumSet.allOf(IntegrationArtifactKind.class);}public TechnologyCompilationResult compile(TechnologyCompilationRequest request){return result;}};}
    private TechnologyAdapter grammarRootAdapter(IntegrationTechnology technology,TechnologyCompilationResult result){return new TechnologyAdapter(){public IntegrationTechnology technology(){return technology;}public Set<IntegrationArtifactKind> supportedArtifactKinds(){return java.util.EnumSet.allOf(IntegrationArtifactKind.class);}public Set<IntegrationArtifactKind> semanticRootKinds(){return Set.of(IntegrationArtifactKind.METAMODEL,IntegrationArtifactKind.GRAMMAR);}public TechnologyCompilationResult compile(TechnologyCompilationRequest request){return result;}};}
    private static TechnologyCompilationResult validResult(IntegrationTechnology technology){return new TechnologyCompilationResult(technology,List.of(file("generated.txt")),List.of(),List.of(),List.of("rollback"),List.of(),List.of(),Map.of());}
    private static TechnologyGeneratedFile file(String path){return new TechnologyGeneratedFile(path,"text/plain","ok".getBytes(StandardCharsets.UTF_8),InjectionFileOwnership.GENERATED,true,List.of("people"),Map.of());}
}
